export class GitHub {
 constructor(repo,branch,token){if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo))throw Error('Enter owner/repository.');this.repo=repo;this.branch=branch;this.token=token;this.base='https://api.github.com/repos/'+repo;this.head=null;this.tree=null}
 async call(path,{method='GET',body,raw=false}={}){const response=await fetch(this.base+path,{method,headers:{Accept:raw?'application/vnd.github.raw+json':'application/vnd.github+json',Authorization:'Bearer '+this.token,'X-GitHub-Api-Version':'2022-11-28',...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});if(!response.ok){let detail='';try{detail=(await response.json()).message}catch{}const e=Error(response.status===409||response.status===422?'The repository changed, or GitHub rejected the update. Reload latest before saving; your editor text is still here.':`GitHub ${response.status}: ${detail||'Request failed'}`);e.status=response.status;throw e}if(response.status===204)return null;return response.json()}
 async snapshot(){const ref=await this.call('/git/ref/heads/'+encodeURIComponent(this.branch));const commit=await this.call('/git/commits/'+ref.object.sha);this.head=ref.object.sha;this.tree=commit.tree.sha}
 async read(path,fallback){try{return await this.call('/contents/'+path.split('/').map(encodeURIComponent).join('/')+'?ref='+this.head,{raw:true})}catch(e){if(e.status===404)return fallback;throw e}}
 async commit(files,message){if(!this.head)throw Error('Connect first.');const entries=[];for(const f of files){if(f.bytes){const blob=await this.call('/git/blobs',{method:'POST',body:{content:base64(f.bytes),encoding:'base64'}});entries.push({path:f.path,mode:'100644',type:'blob',sha:blob.sha})}else entries.push({path:f.path,mode:'100644',type:'blob',content:typeof f.data==='string'?f.data:JSON.stringify(f.data,null,2)+'\n'})}const tree=await this.call('/git/trees',{method:'POST',body:{base_tree:this.tree,tree:entries}});const commit=await this.call('/git/commits',{method:'POST',body:{message,tree:tree.sha,parents:[this.head]}});await this.call('/git/refs/heads/'+encodeURIComponent(this.branch),{method:'PATCH',body:{sha:commit.sha,force:false}});this.head=commit.sha;this.tree=tree.sha;return commit.sha}
 async dispatch(full=false){return this.commit([{path:'content/refresh-request.json',data:{requested_at:new Date().toISOString(),deep_scan:!!full}}],full?'Request deep archive scan':'Request Daily Star refresh')}
 disconnect(){this.token='';this.head=null;this.tree=null}
}
export function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=32768)s+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(s)}
